const json = (o, s = 200) => new Response(JSON.stringify(o), { status: s, headers: { "content-type": "application/json" } });

export class Room extends DurableObject {
  async fetch(req) {
    if (req.headers.get("Upgrade") !== "websocket") return new Response("Expected websocket", { status: 426 });
    const [client, server] = Object.values(new WebSocketPair());
    const id = crypto.randomUUID().slice(0, 8);
    this.ctx.acceptWebSocket(server);
    server.serializeAttachment({ id });
    server.send(JSON.stringify({ id }));
    return new Response(null, { status: 101, webSocket: client });
  }
  webSocketMessage(ws, msg) {
    if (typeof msg !== "string" || msg.length > 20000) return;
    let m;
    try { m = JSON.parse(msg); } catch { return; }
    const me = (ws.deserializeAttachment() || {}).id;
    const out = JSON.stringify({ t: String(m.t || "").slice(0, 20), d: m.d, p: me });
    for (const s of this.ctx.getWebSockets()) { try { s.send(out); } catch {} }
  }
  webSocketClose(ws, code) { try { ws.close(code); } catch {} }
}

export default {
  async fetch(req, env) {
    const u = new URL(req.url);
    if (u.pathname.startsWith("/api/room/")) {
      const code = decodeURIComponent(u.pathname.slice(10)).toLowerCase().replace(/[^a-z0-9-]/g, "").slice(0, 20);
      if (!code) return new Response("Bad room", { status: 400 });
      return env.ROOM.get(env.ROOM.idFromName(code)).fetch(req);
    }
    if (u.pathname === "/api/ai" && req.method === "POST") {
      const origin = req.headers.get("Origin");
      if (origin && new URL(origin).host !== u.host) return json({ error: "forbidden" }, 403);
      if (!env.GEMINI_API_KEY) return json({ error: "AI key is not set" }, 500);
      let b;
      try { b = await req.json(); } catch { return json({ error: "bad request" }, 400); }
      const parts = [{ text: String(b.prompt || "").slice(0, 30000) }];
      for (const im of (b.images || []).slice(0, 4)) parts.push({ inline_data: { mime_type: im.mime || "image/jpeg", data: im.data } });
      const model = env.MODEL || "gemini-2.5-flash";
      const r = await fetch("https://generativelanguage.googleapis.com/v1beta/models/" + model + ":generateContent", {
        method: "POST",
        headers: { "content-type": "application/json", "x-goog-api-key": env.GEMINI_API_KEY },
        body: JSON.stringify({ contents: [{ role: "user", parts }] }),
      });
      if (!r.ok) return json({ error: "AI error " + r.status }, 502);
      const j = await r.json();
      const text = ((j.candidates && j.candidates[0] && j.candidates[0].content && j.candidates[0].content.parts) || []).map(p => p.text || "").join("");
      return json({ text });
    }
    return new Response(HTML, { headers: { "content-type": "text/html; charset=utf-8" } });
  },
};
